\subsection{Le théorème de Tsen.}\label{I:3-2}





\begin{definitiondotdash}\label{I:3-2-1}
On dit qu'un corps $K$ est $C_1$ si tout polynôme homogène non constant 
$f(x_1,\dotsc,x_n)$ de degré $d<n$ a un zéro non trivial.
\end{definitiondotdash}





\PrintPage{31}\begi"}, {"language": "en", "label": "I:3-2-1", "file": "deliverables/EN/SGA4HALF_EN_corrected_apparatus.tex", "line": 2017, "witness": "homologie galoisienne}}{\cite{se94}}.)

\subsection{Tsen's theorem}\label{I:3-2}

\begin{definition}\label{I:3-2-1}
A field $K$ is called $C_1$ if every nonconstant homogeneous polynomial
$f(x_1,\dotsc,x_n)$ of degree $d<n$ has a nontrivial zero.
\end{definition}

\PrintPage{31}\begin{propositi"}]

